import React, { useEffect, useState } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import api from '../api/axios';
import { useAuth } from '../api/AuthContext';

export default function InternshipDetail() {
  const { id } = useParams();
  const [internship, setInternship] = useState(null);
  const [msg, setMsg] = useState('');
  const { user } = useAuth();
  const navigate = useNavigate();

  useEffect(() => {
    api.get(`/internships/${id}`).then(r => setInternship(r.data)).catch(() => navigate('/internships'));
  }, [id]);

  const handleApply = async () => {
    try {
      await api.post(`/applications/apply/${id}`);
      setInternship(prev => ({ ...prev, applied: true }));
      setMsg('Application recorded! Redirecting to company site...');
      setTimeout(() => window.open(internship.applyUrl, '_blank'), 1500);
    } catch (err) {
      setMsg(err.response?.data?.message || 'Already applied');
    }
  };

  if (!internship) return <div className="loading">Loading...</div>;

  return (
    <div className="detail-page">
      <div className="detail-card">
        <h1>{internship.title}</h1>
        <div className="company-name">{internship.company}</div>
        {msg && <div className="success-msg">{msg}</div>}
        <div className="detail-section">
          <h4>Description</h4>
          <p>{internship.description || 'No description provided.'}</p>
        </div>
        <div className="detail-section">
          <h4>Stipend</h4>
          <p>{internship.stipend || 'Not specified'}</p>
        </div>
        <div className="detail-section">
          <h4>Last Date to Apply</h4>
          <p>{internship.deadline}</p>
        </div>
        <div className="detail-section">
          <h4>Eligible Departments</h4>
          <div className="tags">{internship.eligibleDepartments?.map(d => <span key={d} className="tag">{d}</span>)}</div>
        </div>
        <div className="detail-section">
          <h4>Eligible Batches</h4>
          <div className="tags">{internship.eligibleBatches?.map(b => <span key={b} className="tag tag-batch">{b}</span>)}</div>
        </div>
        <div className="detail-section">
          <h4>Total Applicants</h4>
          <p>{internship.applicantCount}</p>
        </div>
        <div className="detail-actions">
          {user?.role === 'STUDENT' && (
            internship.applied ? (
              <span className="badge-applied">Already Applied</span>
            ) : internship.eligible ? (
              <button className="btn btn-success" onClick={handleApply}>Apply Now</button>
            ) : (
              <span className="badge-ineligible">Not Eligible</span>
            )
          )}
          {user?.role === 'ADMIN' && internship.applyUrl && (
            <a href={internship.applyUrl} target="_blank" rel="noreferrer" className="btn btn-primary">Open Application Link</a>
          )}
          <button className="btn btn-secondary" onClick={() => navigate(-1)}>Back</button>
        </div>
      </div>
    </div>
  );
}
